import{_ as a,o as t,c as o,a4 as i}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"CRDT：无冲突数据类型","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/replication/crdt.md","filePath":"distributed/replication/crdt.md","lastUpdated":1788475713000}'),s={name:"distributed/replication/crdt.md"};function r(n,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="crdt-无冲突数据类型" tabindex="-1">CRDT：无冲突数据类型 <a class="header-anchor" href="#crdt-无冲突数据类型" aria-label="Permalink to &quot;CRDT：无冲突数据类型&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p><strong>CRDT (Conflict-Free Replicated Data Type)</strong> 是 Marc Shapiro et al. 2011 (INRIA) 提出的&quot;分布式数据结构数学统一理论&quot;——在最终一致性系统里, 只要每个操作具备<strong>commutativity (可交换)</strong> + <strong>associativity (可结合)</strong> + <strong>idempotency (幂等)</strong>, 多节点任意顺序应用 op 最终都收敛到同一状态, 不需要协调或共识。CRDT 让无主/多主复制免 vector clock sibling 选择, 让 collaborative editing 不走 OT 的复杂 transformation matrix。 例: Riak DataType (counters/sets/maps), Redis CRDT, Automerge, Yjs, SoundCloud Roshi, Figma 的多人编辑都靠 CRDT。 本章梳理 state-based vs op-based CRDT, 加入常见类型 (G-Counter / PN-Counter / G-Set / 2P-Set / OR-Set / LWW-Register / LWW-Map / RGA / Text), 收敛证明与&quot;为什么需要 tombstones 而非简单 delete&quot;, typical 生产事故 + 协同编辑器对比 (Automerge vs Yjs vs Google Docs OT)。</p><hr><h2 id="一、问题-conflict-resolution-without-central-coordinator" tabindex="-1">一、问题:Conflict Resolution Without Central Coordinator <a class="header-anchor" href="#一、问题-conflict-resolution-without-central-coordinator" aria-label="Permalink to &quot;一、问题:Conflict Resolution Without Central Coordinator&quot;">​</a></h2><h3 id="vector-clock-sibling-的问题" tabindex="-1">Vector Clock Sibling 的问题 <a class="header-anchor" href="#vector-clock-sibling-的问题" aria-label="Permalink to &quot;Vector Clock Sibling 的问题&quot;">​</a></h3><p>Dynamo / Riak default vector clock 让 user / application resolve conflict: 看到 <code>siblings = [VC1: A=1,B=0 ; VC2: A=0,B=1]</code>, application 必须给出 merge function. 写 application-level merge 复杂且易错:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// shopping cart 复制抖镖 – 用户加 不同 — difference in conflict resolve</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cart_NY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {apple, banana}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cart_SF </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {apple, cherry}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">merge_elems </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cart_NY ∪ cart_SF </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {apple, banana, cherry}  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// OK!</span></span></code></pre></div><p>但若 <code>delete</code> 也需要支持, 简单 union 不能反&quot;deleted&quot;——计数 set deletion 需要 tombstone.</p><p>CRDT 解决这个: 让 data structure 本身的 merge function 是数学上 associative + commutative + idempotent, 则 replicas 任顺序收敛。</p><hr><h2 id="二、state-based-vs-op-based-crdt" tabindex="-1">二、State-based vs Op-based CRDT <a class="header-anchor" href="#二、state-based-vs-op-based-crdt" aria-label="Permalink to &quot;二、State-based vs Op-based CRDT&quot;">​</a></h2><p>Shapiro et al. 定义两种 CRDT:</p><h3 id="state-based-cvrdt-convergent-replicated-data-type" tabindex="-1">State-based (CvRDT: Convergent Replicated Data Type) <a class="header-anchor" href="#state-based-cvrdt-convergent-replicated-data-type" aria-label="Permalink to &quot;State-based (CvRDT: Convergent Replicated Data Type)&quot;">​</a></h3><ul><li>每节点独立持本地 state。</li><li>节点不发送 op, 只发送整个<strong>state</strong> (或 delta-state) 给其他 replica。</li><li>merges: <code>join(s1, s2) = s1 ⊔ s2</code>必须 <strong>commutative, associative, idempotent</strong>。</li></ul><p>最终收敛条件 (bounded semilattice): join 算子构成 partial-order semilattice (有 least upper bound), 所有 join 都单调 = 收敛后状态。</p><h3 id="op-based-cmrdt-commutative-replicated-data-type" tabindex="-1">Op-based (CmRDT: Commutative Replicated Data Type) <a class="header-anchor" href="#op-based-cmrdt-commutative-replicated-data-type" aria-label="Permalink to &quot;Op-based (CmRDT: Commutative Replicated Data Type)&quot;">​</a></h3><ul><li>节点不传整个 state, 直接传 op。</li><li>每个 op 必须是 commutative + idempotent (因为 message may re-arrive or arrive more than once)。</li><li><strong>!) requirement</strong>: Casual broadcast——若 op a 因果先 op b, a 必须先到达所有 replica。</li></ul><p>Op-based 节省带宽、时延, 但需 underlying casual broadcast (vector clock)。 Riak DT 与 Yjs/Automerge mixed state-based 优点 + delta-state 优化。</p><p>工业一般用 state-based + delta-state, 因为 op-based 需要 casual 顺序保障开销。</p><hr><h2 id="三、常见-crdt-类型" tabindex="-1">三、常见 CRDT 类型 <a class="header-anchor" href="#三、常见-crdt-类型" aria-label="Permalink to &quot;三、常见 CRDT 类型&quot;">​</a></h2><h3 id="_1-g-counter-grow-only-counter-单调不减" tabindex="-1">1. G-Counter (Grow-only Counter, 单调不减) <a class="header-anchor" href="#_1-g-counter-grow-only-counter-单调不减" aria-label="Permalink to &quot;1. G-Counter (Grow-only Counter, 单调不减)&quot;">​</a></h3><p>State: 每节点 i 维护独立 counter <code>c_i</code>, 初始 0. Op <code>inc()</code>: <code>c_i++</code> at local node i. Query <code>value()</code>: <code>Σ c_i</code> over all i. Merge: <code>c_i = max(c_i_a, c_i_b) for each i</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node A: c_A=5, c_B=0  value=5</span></span>
<span class="line"><span>node B: c_A=0, c_B=3  value=3</span></span>
<span class="line"><span>after merge on A: c_A=5, c_B=3, value=8</span></span></code></pre></div><p><code>max</code> + idempotent ⇒ CRDT。</p><h3 id="_2-pn-counter-positive-negative-counter" tabindex="-1">2. PN-Counter (Positive-Negative Counter) <a class="header-anchor" href="#_2-pn-counter-positive-negative-counter" aria-label="Permalink to &quot;2. PN-Counter (Positive-Negative Counter)&quot;">​</a></h3><p>不能直接复用 G-Counter 因为 counter decrements 是非 commutative matching monotonic increases. 解决方法:</p><p>State: 两 G-Counter, <code>P</code> (positive) + <code>N</code> (negative). Op <code>inc()</code>: <code>P_i++</code>; Op <code>dec()</code>: <code>N_i++</code>. Query <code>value()</code>: <code>Σ P_i - Σ N_i</code>. Merge: per-node max on each of P and N.</p><h3 id="riak-counters" tabindex="-1">Riak Counters <a class="header-anchor" href="#riak-counters" aria-label="Permalink to &quot;Riak Counters&quot;">​</a></h3><p>Riak DT Counter = PN-Counter。 性能警告: 内部 vector clock chain 增 large, ops 100k+ 之后 operation tensor 膨胀 + potential 性能下降 — Riak pin 自动&quot;GC + archive&quot;措施.</p><h3 id="_3-g-set-grow-only-set-加入只" tabindex="-1">3. G-Set (Grow-only Set, 加入只) <a class="header-anchor" href="#_3-g-set-grow-only-set-加入只" aria-label="Permalink to &quot;3. G-Set (Grow-only Set, 加入只)&quot;">​</a></h3><p>只支持 <code>add(e)</code>, 不允许 remove. State: Set S. Op <code>add(e)</code>: <code>S = S ∪ {e}</code>. Merge: <code>S = S_a ∪ S_b</code>.</p><h3 id="_4-2p-set-two-phase-set-加追删" tabindex="-1">4. 2P-Set (Two-Phase Set, 加追删) <a class="header-anchor" href="#_4-2p-set-two-phase-set-加追删" aria-label="Permalink to &quot;4. 2P-Set (Two-Phase Set, 加追删)&quot;">​</a></h3><p>支持 add 与 remove, 但每 element 最多 add 一次 + remove 一次。</p><p>State: 两个 G-Set, <code>A</code> (added), <code>R</code> (removed). Op <code>add(e)</code>: <code>A = A ∪ {e}</code>. Op <code>remove(e)</code>: 必须先 add, <code>R = R ∪ {e}</code> (但 transient add-remove-proof: tombstone)。 Query <code>contains(e)</code>: <code>e ∈ A ∧ e ∉ R</code>.</p><p>风险: 添加 remove 后无法 re-add——同 e 再 add 仍 contains=false (因 R 已有 e). 适合 &quot;tag collective&quot; 使用, 不适合 dynamic add/remove 反复 use case.</p><h3 id="_5-or-set-observed-remove-set-—-工业常用" tabindex="-1">5. OR-Set (Observed-Remove Set) — 工业常用 <a class="header-anchor" href="#_5-or-set-observed-remove-set-—-工业常用" aria-label="Permalink to &quot;5. OR-Set (Observed-Remove Set) — 工业常用&quot;">​</a></h3><p>状态稳定 (与2P-Set 对比): 每次添加生成 <strong>唯一 tag</strong> (uuid), 删除只删 add 中见过的 tag.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add(e): generate new tag t, A = A ∪ {(e, t)}</span></span>
<span class="line"><span>remove(e): collect all (e, t) seen locally, R = R ∪ observed_tags</span></span>
<span class="line"><span>contains(e): ∃ t such that (e, t) ∈ A ∧ (e, t) ∉ R</span></span>
<span class="line"><span>merge: A_merged = A_a ∪ A_b ; R_merged = R_a ∪ R_b</span></span></code></pre></div><p>加后再删可再 add — 新 tag 条件唯一 (** remove only affects observed tags**.</p><p>工业 use case: Riak DT Set, Figma multi-collaboration shared states.</p><h3 id="_6-lww-register-last-writer-wins-register" tabindex="-1">6. LWW-Register (Last-Writer-Wins Register) <a class="header-anchor" href="#_6-lww-register-last-writer-wins-register" aria-label="Permalink to &quot;6. LWW-Register (Last-Writer-Wins Register)&quot;">​</a></h3><p>State: value v + timestamp t. Op <code>set(v_new, t)</code>: if t &gt; t_current → set local v to v_new. Merge: choose side with larger t.</p><p>** 注意**: timestamp 比较 wall clock 不安全 (clock skew) — 必须用 monotonic + hybrid clock (HLC)。</p><h3 id="_7-lww-map" tabindex="-1">7. LWW-Map <a class="header-anchor" href="#_7-lww-map" aria-label="Permalink to &quot;7. LWW-Map&quot;">​</a></h3><p>LWW-Map 不 commute on per-key bases in general. var <code>m[k] = LWW-Register</code> for each k. 各 key 之间可并行 update, 同 key 内以 LWW-Register 内部 timestamp 比较——但是 Map.remove + Map.add 同对应 key 时钟对间 race 复杂. Yjs 与 Automerge 都不直接使用 LWW-Map, 而是 nested OR-Set + OR-Map 的变种.</p><h3 id="_8-rga-replicated-growable-array-—-协同编辑" tabindex="-1">8. RGA (Replicated Growable Array) — 协同编辑 <a class="header-anchor" href="#_8-rga-replicated-growable-array-—-协同编辑" aria-label="Permalink to &quot;8. RGA (Replicated Growable Array) — 协同编辑&quot;">​</a></h3><p>RGA 是文字/列表顺序的核心 CRDT, 用 unique ID per element + <code>after</code> reference:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char id = (timestamp, replica_id), parent_id (前一个 char 的 id)</span></span>
<span class="line"><span>insert((content, id, parent_id)):</span></span>
<span class="line"><span>  if parent_id 已在 list:</span></span>
<span class="line"><span>     insert new entry 在 parent_id 之后, 维护 tie-breaker desc 顺序 by id</span></span>
<span class="line"><span>remove(id):</span></span>
<span class="line"><span>  mark tombstone</span></span></code></pre></div><p>merge: 同时维护所有 insertions + tombstones, 各 replica 收敛 by ID lexicographic compare for siblings.</p><h3 id="yjs-优化" tabindex="-1">Yjs 优化 <a class="header-anchor" href="#yjs-优化" aria-label="Permalink to &quot;Yjs 优化&quot;">​</a></h3><p>Yjs 的 YText/RGA 实现 internal “block” skip-list。 每用户写时记录 origin id 但 leaf reading 延 through skip-list 子 BLOCK = O(1) lookup instead of O(N) treewalk. Yjs 是 2017 Kevin Jahns built; Figma 之类 collaborate 编辑器常见路径. 比 Google Docs OT 更 distributed.</p><hr><h2 id="四、crdt-收敛性证明" tabindex="-1">四、CRDT 收敛性证明 <a class="header-anchor" href="#四、crdt-收敛性证明" aria-label="Permalink to &quot;四、CRDT 收敛性证明&quot;">​</a></h2><h3 id="semilattice" tabindex="-1">Semilattice <a class="header-anchor" href="#semilattice" aria-label="Permalink to &quot;Semilattice&quot;">​</a></h3><p>定义: 部分序关系 <code>≤</code> 且 任何两元素有 least upper bound (lub) <code>a ⊔ b</code>.</p><p>CRDT 状态空间 S 上, <code>join : S × S → S</code> 取 lub. <code>join</code> 满足:</p><ol><li>Commutativity: <code>a ⊔ b = b ⊔ a</code></li><li>Associativity: <code>a ⊔ (b ⊔ c) = (a ⊔ b) ⊔ c</code></li><li>Idempotency: <code>a ⊔ a = a</code></li></ol><h3 id="收敛定理" tabindex="-1">收敛定理 <a class="header-anchor" href="#收敛定理" aria-label="Permalink to &quot;收敛定理&quot;">​</a></h3><p>若 op 满足 <strong>commutativity + idempotency</strong> (state-based 中 via join), 则无论 op 顺序, 最终所有 replica 收敛到 <code>lub(initial_state, all_ops)</code>。</p><p>证明: 每节点最终都 join 所有 ops. 因 join 单调增 + 上界存在 + lub 唯一 ⇒ 各 replica 终态一致。</p><p><strong>关键</strong>: remove ops 如何收敛——simple remove 不 commute (<code>add a; remove a; merge</code> ≠ same as <code>remove a; merge; add a</code>)。 tombstones 与 OR-Set 都是这个 limitation 的解法。</p><hr><h2 id="五、应用例" tabindex="-1">五、应用例 <a class="header-anchor" href="#五、应用例" aria-label="Permalink to &quot;五、应用例&quot;">​</a></h2><h3 id="riak-dt" tabindex="-1">Riak DT <a class="header-anchor" href="#riak-dt" aria-label="Permalink to &quot;Riak DT&quot;">​</a></h3><p>Basho Riak 2.0+ 提供 built-in types:</p><ul><li><code>counter</code>: PN-Counter</li><li><code>set</code>: OR-Set</li><li><code>map</code>: nested CRDT map (counter, set, register, flag per key)</li><li><code>register</code>: LWW-Register</li><li><code>flag</code>: boolean CRDT</li></ul><p>bucket API:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>riak.update_bucket_type(&quot;counters&quot;, ...)</span></span>
<span class="line"><span>riak.bucket(&quot;counts&quot;).update(&quot;likes&quot;, increment=1)</span></span></code></pre></div><p>避免了 application 自己组织 sibling merge。</p><h3 id="automerge" tabindex="-1">Automerge <a class="header-anchor" href="#automerge" aria-label="Permalink to &quot;Automerge&quot;">​</a></h3><p>Automerge (2017, Ink &amp; Switch) 是纯 JS library CRDT + JSON documents. JavaScript 的 <code>automerge.from(initial)</code> 创 doc, <code>.change(doc, m =&gt; m.todos.push({...}))</code> 修改. 内部是 OR-Set + RGA + LWW-Map nested.</p><p>Atrium, Habit, rtags —— family collaborative paper tool。 Notion-like data stores. 生产环境 slow broadcast presence ensured 跨 DC collaborative editing.</p><h3 id="yjs" tabindex="-1">Yjs <a class="header-anchor" href="#yjs" aria-label="Permalink to &quot;Yjs&quot;">​</a></h3><p>Yjs 是 Kevin Jahns 写 (2017), 体积小 (60KB JS) + 性能 peak (100+ users simultaneously). 应用: Notion Quip-like collab editor, Atlassian Trello-like product collaborative viewer.</p><h3 id="redis-crdts-redis-enterprise-active-active" tabindex="-1">Redis CRDTs (Redis Enterprise Active-Active) <a class="header-anchor" href="#redis-crdts-redis-enterprise-active-active" aria-label="Permalink to &quot;Redis CRDTs (Redis Enterprise Active-Active)&quot;">​</a></h3><p>Redis Enterprise 提供 server-side CRDTs: counters, sets, hashes, strings all sync replicate across 多个 region (active-active). Counter for inventory increments monotone tests no lost update.</p><h3 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h3><p>Figma 的多人实时协作没有直接套用现成 CRDT：文档是嵌套的图形树，通用 CRDT 在其上开销过高。实际做法是<strong>中心服务器定序 + 增量操作流</strong>（类 OT 的简化）：客户端把属性修改作为增量 op 发给服务器，服务器以单一权威顺序广播给其他客户端。每个对象属性对用 last-writer-wins 语义合并，删除与插入用自定义的混合规则处理。配合 CDN 延迟广播降低带宽峰值——<strong>当存在可信中心节点时, 简单定序往往优于分布式收敛协议</strong>, 这是与 CRDT 适用边界的重要对照。</p><hr><h2 id="六、典型问题" tabindex="-1">六、典型问题 <a class="header-anchor" href="#六、典型问题" aria-label="Permalink to &quot;六、典型问题&quot;">​</a></h2><h3 id="crdt-tombstone-膨胀" tabindex="-1">CRDT Tombstone 膨胀 <a class="header-anchor" href="#crdt-tombstone-膨胀" aria-label="Permalink to &quot;CRDT Tombstone 膨胀&quot;">​</a></h3><p>G-/OR-Set delete operation 不真删——保 tombstones for concurrent merge. 长时间 set 加入 + 删除, 数 MB 内存占用. 解决 = GC: 只在所有 replica 都知道 tombstone 存在这之后删—— causal tracking 要 vector-clock GC.</p><h3 id="or-set-tag-exponential" tabindex="-1">OR-Set Tag Exponential <a class="header-anchor" href="#or-set-tag-exponential" aria-label="Permalink to &quot;OR-Set Tag Exponential&quot;">​</a></h3><p>Each <code>add(e)</code> 生成 new tag. Repetitive add/remove 写 ~100k ops/set 之后, A 与 R set 元素 count baptized millions.</p><p>Figma 修复: used delta-state CRDTs (delta-CRDTs, Almeida et al. 2018) 只广播增量状态.</p><h3 id="lww-with-clock-skew" tabindex="-1">LWW with Clock Skew <a class="header-anchor" href="#lww-with-clock-skew" aria-label="Permalink to &quot;LWW with Clock Skew&quot;">​</a></h3><p>NTP skew 10ms: client A <code>set x=A</code> at T100, client B <code>set x=B</code> at T100— inconsistent order ⟹ B not always wins on all replicas.</p><p>Fix: HLC + monotonic local count. Riak default uses vclock + wall_ms.</p><h3 id="concurrent-modes-drops" tabindex="-1">Concurrent Modes Drops <a class="header-anchor" href="#concurrent-modes-drops" aria-label="Permalink to &quot;Concurrent Modes Drops&quot;">​</a></h3><p>CRDT Map 的 <code>remove(k)</code> + 并发 <code>set(k, v)</code>: 一个想 remove k + 但下次 add 想被合并—— 定义文档 differ 不总可predict. Riak DT Map 用 OR-Map &quot;element context&quot; tracking 解决: remove 只 mark &quot;remove removed at observed states&quot;, 后加 v 在不同 OR-Set tag, 决战必然附加. 但同时复现 users 见 &quot;k 存在&quot; + &quot;k 不存在&quot; 是 widely ambiguous. 文档 mention this in <a href="./../concepts/ordering">ordering</a>.</p><hr><h2 id="七、易错清单" tabindex="-1">七、易错清单 <a class="header-anchor" href="#七、易错清单" aria-label="Permalink to &quot;七、易错清单&quot;">​</a></h2><ol><li><strong>CRDT ≠ 任意 sequence 状态兼容</strong>: op 必须 commutative + idempotent, 写 sequence ops (list.append; list.reverse + append; ...)</li><li><strong>LWW-Register timestamp mismatch</strong>: 必须 hybrid clock (HLC) + monotonic counter per-node — wall clock alone 不可。</li><li><strong>CRDT Map.remove + concurrent Map.set(k, v)</strong> → if not using OR-Set with causal state tracking, 设置 (v) 可能 silently dropped.</li><li><strong>Tombstones 必 GC</strong>: OR-Set remove 写 tombstones add up; 必须 GC 与 vector clock 因果跟踪同步.</li><li><strong>CRDT 序列化膨胀</strong>: 远远多于 update state after上百 bytes data; 大 apps 需要 delta-CRDTs include 编码驱动的 delta-state ship优化.</li><li><strong>协同编辑器要 Carefully handle &quot;anchor&quot;</strong> — 共同 characteristic seed 根 character 0 anchor records to insert下一个 char的位置—— if all char removed, top is not 0 anchor, 而是 deleted anchor with tombstones on the root.</li><li><strong>CRDT ≠ Strong consistency</strong>: CRDT 保证 eventual converge + 不会丢更新但 promise 不是 Stale-Snap &quot;see client writes own writes for business&quot; — 保 防epoch: branch sessions need combine with sessionconfig to ensure RYW.</li></ol><hr><h2 id="八、这一章带走的东西" tabindex="-1">八、这一章带走的东西 <a class="header-anchor" href="#八、这一章带走的东西" aria-label="Permalink to &quot;八、这一章带走的东西&quot;">​</a></h2><ol><li>CRDT 用 join-semilattice 让免 merge function conflict-free; commutativity + idempotency 是设计原点.</li><li>工业常用 CRDT 类型: G-Counter, PN-Counter, G-Set, 2P-Set, OR-Set, LWW-Register, OR-Map, RGA (Text).</li><li>OR-Set 用 unique tag per add 是正确处理 add-after-remove 的关键, 避开 2P-Set &quot;remove forever&quot; 处理.</li><li>RGA (Replicated Growable Array) 是协同编辑器的基础 CRDT (Figma Yjs Notion-like).</li><li>CRDT 的代价: tombstone accumulation + GC complexity; delta-state broadcast 是性能修案.</li><li>CRDT ≠ strong consistency. only eventual. 与 linearizability (Spanner) 与 RYW (Dynamo) 不同, 财务线 transaction 推荐仍 Paxos + serial.</li></ol><hr><p>下一节 → <a href="./repair">读修复 / 反熵 / hinted handoff</a></p>`,100)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
